head.script:
		var pBoardInfo = WebSquare.net.getParameter( "boardInfo" );  // 게시판정보
     	var pStatementId = WebSquare.net.getParameter( "statementId" );	//글번호
		var pBoardTyp = WebSquare.net.getParameter( "boardTyp" );	//게시판유형
		
		var PAGE_CNT = WebSquare.net.getParameter( "PAGE_CNT" );
		
      /**************************************************************************
		* function    : cbmDataInit
		* Description : 게시판 콤보 리스트 설정
		* Parameter   : null
		* Return      : null
		**************************************************************************/	
		function init() {
			this.document.title=divisionNm;
			resizeIframe();
			
			searchData();
		}
		
		
		/**************************************************************************
		 * function    : searchData
		 * Description : 게시판 조회
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/	
		function searchData() {
			WebSquare.ModelUtil.removeChildNodes( "BISComBoardDTO" );
        	
        	BISComBoardDTO =  {"BISComBoardDTO":{}};
        	
        	setValue("BISComBoardDTO/boardID", pBoardInfo);
        	setValue("BISComBoardDTO/boardTyp", pBoardTyp);
        	setValue("BISComBoardDTO/statementId", pStatementId);
        	/*
        	pfm_insertValue(BISComBoardDTO,"boardID", pBoardInfo);
        	pfm_insertValue(BISComBoardDTO,"boardTyp", pBoardTyp);
			pfm_insertValue(BISComBoardDTO,"statementId", pStatementId);
	      */
        	//callProFrame("BIS-COM","BISComBoardSO","selectDetail2",BISComBoardDTO, "BISComBoardDTO","resp");
			callProFrame("BIS-COM","BISComBoardSO","selectKFREDetail",BISComBoardDTO, "BISComBoardDTO","resp");
		}

		
     	/**************************************************************************
      * function    : callBack
      * Description : submission 실행 후 Callback
      * Parameter   : retAction(submission 실행 Action), rowCount(조회 목록 총 건수)
      * Return      : null
      **************************************************************************/
     	function callBack(svcId,fnId,strResp) {   
     		if (svcId == "BISComBoardSO") {
     			if (fnId == "selectDetail2") {
     				content.setValue( textEncoding(getValue("resp/root/message/BISComBoardDTO/content")).replaceAll("&#xA;", "<br/>") );
     			
     				var DETAIL_FILE_NM = getValue("resp/root/message/BISComBoardDTO/attachFile");
     				
     				for(var i=0; i<DETAIL_FILE_NM.split("^").length; i++){
     					generatorFileList.insert();
     					
     					if(i>0){
	     					group67.setSize( group67.getSize( "width" ) , group67.getSize( "height" )+(i*13) );
	     					group68.setSize( group68.getSize( "width" ) , group68.getSize( "height" )+(i*13) );
	     					group69.setSize( group69.getSize( "width" ) , group69.getSize( "height" )+(i*13) );
     					}
     				}
     				
     				for(var a=0; a<DETAIL_FILE_NM.split("^").length; a++){
     					var str = DETAIL_FILE_NM.split("^")[a];
     					
     					var arrData = str.split("|");
						generatorFileList.getChild(a, "ATTACH_FILESEQ").setValue( arrData[0] );
						generatorFileList.getChild(a, "ATTR_NM").setValue( arrData[1] );
						generatorFileList.getChild(a, "ATTACH_SAVE_FILEPATH").setValue( arrData[2] );
						generatorFileList.getChild(a, "ATTACH_FILENM").setValue( textEncoding(arrData[3]) );
						generatorFileList.getChild(a, "ORIGINAL_FILENAME").setValue( textEncoding(arrData[4]) );
						generatorFileList.getChild(a, "imgAttachFile").setTitle( textEncoding(arrData[4]) );
					}
					resizeIframe();
     			} else if (fnId == "selectKFREDetail") {
				
					console.log("view selectKFREDetail callback..");
				
     				content.setValue( textEncoding(getValue("resp/root/message/BISComBoardDTO/content")).replaceAll("&#xA;", "<br/>") );
     			
     				var DETAIL_FILE_NM = getValue("resp/root/message/BISComBoardDTO/attachFile");
     				
     				for(var i=0; i<DETAIL_FILE_NM.split("^").length; i++){
     					generatorFileList.insert();
     					
     					if(i>0){
	     					group67.setSize( group67.getSize( "width" ) , group67.getSize( "height" )+(i*13) );
	     					group68.setSize( group68.getSize( "width" ) , group68.getSize( "height" )+(i*13) );
	     					group69.setSize( group69.getSize( "width" ) , group69.getSize( "height" )+(i*13) );
     					}
     				}
     				
     				for(var a=0; a<DETAIL_FILE_NM.split("^").length; a++){
     					var str = DETAIL_FILE_NM.split("^")[a];
     					
     					var arrData = str.split("|");
						generatorFileList.getChild(a, "ATTACH_FILESEQ").setValue( arrData[0] );
						generatorFileList.getChild(a, "ATTR_NM").setValue( arrData[1] );
						generatorFileList.getChild(a, "ATTACH_SAVE_FILEPATH").setValue( arrData[2] );
						generatorFileList.getChild(a, "ATTACH_FILENM").setValue( textEncoding(arrData[3]) );
						generatorFileList.getChild(a, "ORIGINAL_FILENAME").setValue( textEncoding(arrData[4]) );
						generatorFileList.getChild(a, "imgAttachFile").setTitle( textEncoding(arrData[4]) );
					}
					resizeIframe();
     			}	
     		}
		}
		
		/**************************************************************************
		 * function    : fileDownloadView
		 * Description : 파일 다운로드
		 * Parameter   : null
		 * Return      : null
		 **************************************************************************/
		function fileDownloadView(obj) {
			var str1 = eval("generatorFileList_"+obj.getID().split("_")[1]+"_ATTR_NM").getValue();
			var str2 = eval("generatorFileList_"+obj.getID().split("_")[1]+"_ATTACH_SAVE_FILEPATH").getValue();
			var str3 = eval("generatorFileList_"+obj.getID().split("_")[1]+"_ATTACH_FILENM").getValue();
			var str4 = eval("generatorFileList_"+obj.getID().split("_")[1]+"_ORIGINAL_FILENAME").getValue();
			comFileDownload(str1,str2,str3,str4);
		}
		
		
		/**************************************************************************
       * function    : showMain
       * Description : 목록으로 이동
       * Parameter   : null
       * Return      : null
       **************************************************************************/
      function showMain() {
      	//history.go(-1);
      	parent.maincontent.setSrc("/xml/board/BISItgtBoardListFre.xml"
      										+ "&PAGE_CNT=" + PAGE_CNT
      										+ "&boardInfo=" + pBoardInfo + "&boardTyp=" + pBoardTyp
      										+ "&divisionId=" + divisionId + "&topMenuIndex=" + topMenuIndex
      										);
      }
